(11,'01. TOTAL MES','<?php\n\n$card = array();\n\n$card[\'nome\'] = \'Total Mês\';\n$card[\'valor\'] = \'0,00\';\n$card[\'sql\'] = \"SELECT SUM(FAC001_NF_Valor_Total_Preco)\n                  FROM FAC001 \n             LEFT JOIN DIM001 ON FAC001_DIM001_Id = DIM001_Id \n                 WHERE DIM001_Mes =MONTH(today())-1\n                   AND DIM001_Ano =YEAR(today()) \n                   AND (FAC001_NF_Valor_Total_Preco>0\n                    OR FAC001_NF_Quantidade>0)\";\n$card[\'classe\'] = \'padrao\';\n$card[\'decimais\'] = \'2\';\n$card[\'formato\'] = \"R$ valor\";\n\nreturn $card;\n\n','','2.Vendas mes anterior','S','1',0,2,NULL,NULL),
(12,'04. TICKET MÉDIO','<?php\n\n$card = array();\n\n$card[\'nome\'] = \'Ticket médio\';\n$card[\'valor\'] = \'0,00\';\n$card[\'sql\'] = \"SELECT SUM(FAC001_NF_Valor_Total_Preco)/SUM(FAC001_NF_Quantidade)\n                  FROM FAC001 \n             LEFT JOIN DIM001 ON FAC001_DIM001_Id = DIM001_Id \n                 WHERE DIM001_Mes =MONTH(today())-1\n                   AND DIM001_Ano =YEAR(today()) \n                   AND (FAC001_NF_Valor_Total_Preco>0\n                    OR FAC001_NF_Quantidade>0)\";\n$card[\'classe\'] = \'padrao\';\n$card[\'decimais\'] = 2;\n$card[\'formato\'] = \"R$ valor\";\n\nreturn $card;','','2.Vendas mes anterior','S','1',0,2,NULL,NULL),
(13,'02. MÉDIA DIÁRIA','<?php\n\n$card = array();\n\n$card[\'nome\'] = \'Média dia\';\n$card[\'valor\'] = \'0,00\';\n$card[\'sql\'] = \"SELECT SUM(FAC001_NF_Valor_Total_Preco)/COUNT(DISTINCT FAC001_DIM001_Id)\n                  FROM FAC001 \n             LEFT JOIN DIM001 ON FAC001_DIM001_Id = DIM001_Id \n                 WHERE DIM001_Mes =MONTH(today())-1\n                   AND DIM001_Ano =YEAR(today()) \n                   AND (FAC001_NF_Valor_Total_Preco>0\n                    OR FAC001_NF_Quantidade>0)\";\n$card[\'classe\'] = \'padrao\';\n$card[\'decimais\'] = 2;\n$card[\'formato\'] = \"R$ valor\";\n\nreturn $card;','','2.Vendas mes anterior','S','1',0,2,NULL,NULL),
(14,'03. QTE TICKETS','<?php\n\n$card = array();\n\n$card[\'nome\'] = \'Qte tickets\';\n$card[\'valor\'] = \'0,00\';\n$card[\'sql\'] = \"SELECT SUM(FAC001_NF_Quantidade)\n                  FROM FAC001 \n             LEFT JOIN DIM001 ON FAC001_DIM001_Id = DIM001_Id \n                 WHERE DIM001_Mes =MONTH(today())-1\n                   AND DIM001_Ano =YEAR(today()) \n                   AND FAC001_NF_Quantidade>0\";\n$card[\'classe\'] = \'padrao\';\n$card[\'decimais\'] = 0;\n$card[\'formato\'] = \"valor\";\n\nreturn $card;\n\n','','2.Vendas mes anterior','S','1',0,2,NULL,NULL),
