(25,'02. MÉDIA MENSAL','<?php\n\n$card = array();\n\n$card[\'nome\'] = \'Média mês\';\n$card[\'valor\'] = \'0,00\';\n$card[\'sql\'] = \"SELECT sum(FAC001_NF_Valor_Total_Preco)/count(distinct concat(toString(DIM001_Ano),toString(DIM001_Mes)))\n                  FROM FAC001 \n             LEFT JOIN DIM001 ON FAC001_DIM001_Id = DIM001_Id \n                 WHERE FAC001_NF_Valor_Total_Preco>0\";\n$card[\'classe\'] = \'padrao\';\n$card[\'decimais\'] = 2;\n$card[\'formato\'] = \'R$ valor\';\n\nreturn $card;','','3.Vendas anual','S','1',0,2,NULL,NULL),
